"""sklearn.utils.random — random sampling utilities."""

import numpy as _np


def sample_without_replacement(n_population, n_samples, *, method='auto',
                                random_state=None):
    """Sample ``n_samples`` integers from ``range(n_population)`` without
    replacement."""
    rng = _np.random.default_rng(random_state if isinstance(random_state, int) else None)
    return rng.choice(n_population, size=n_samples, replace=False)
